class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        first = {}
        last = {}
        # Find the first and last occurrence of each character
        for i, ch in enumerate(s):
            if ch not in first:
                first[ch] = i
            last[ch] = i

        intervals = []

        # Find the minimal valid substring starting at each character's first occurrence
        for c, l in first.items():
            r = last[c]
            i = l
            valid = True

            while i <= r:
                x = s[i]
                # If a character inside our bounds appeared before our start index, it's invalid
                if first[x] < l:
                    valid = False
                    break
                # Expand the right bound to include all occurrences of the current character
                if last[x] > r:
                    r = last[x]
                i += 1

            # A valid interval must not span the entire string
            if valid and not (l == 0 and r == len(s) - 1):
                intervals.append((l, r))

        # Greedy Interval Scheduling: Sort by end time to pack maximum non-overlapping intervals
        intervals.sort(key=lambda x: x[1])

        count = 0
        prev_end = -1
        for l, r in intervals:
            if l > prev_end:
                count += 1
                prev_end = r
                # If we've collected enough valid substrings, we can immediately return True
                if count >= k:
                    return True

        return False
